// Statistics per kommun from Kolada (api.kolada.se v3; see data-export/kolada on the claude/kolada-data
// branch), per 100 000 inhabitants:
// - Brå: every reported crime (anmälda brott) in 2024 and 2025, not just the selection Polisen publishes.
//   A rate is by where the crime happened; reports without a place are left out.
// - MCF (formerly MSB): the rescue service's call-outs to building fires and traffic accidents,
//   published as per 1 000 and averaged over several years (see each kind's note).
// Update once a year when Kolada publishes the next year.

export interface StatType {
  id: string;
  /** Kolada's KPI id */
  kpi: string;
  label: string;
  source: string;
  /** How the figure is made, when it is not one year's count */
  note: string | null;
}

